import json
from typing import AnyStr

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import READ_BUFFER_SIZE, SERVER_HOST
from ta_logcollector.utils.enums import PUBLIC_ENUMS


class SocketHandler:
    def __init__(self, log_host, log_port, _socket, socket_blocking=True, socket_timeout=None):
        # type: (str, int, socket.socket, bool, Optional[Union[int, float]]) -> None
        """
        Common network socket handler.

        :param log_host: IP address of logger host
        :param log_port: port of logger host
        :param _socket: network socket
        :param socket_blocking: default True
        :param socket_timeout: in seconds
        """
        self._logger = get_net_logger(log_host, log_port, name=f"SocketHandler_{SERVER_HOST}")
        self._socket = _socket
        self._set_sock_opts(socket_blocking, socket_timeout)
        self._host_address = _socket.getsockname()
        self._client_address = None

    @property
    def client_address(self):
        """
        Get client address data.

        :return: Addresses can be either tuples of varying lengths (AF_INET, AF_INET6, AF_NETLINK, AF_TIPC) or strings (AF_UNIX)
        """
        if self._client_address is None:
            try:
                self._client_address = self._socket.getpeername()
            except OSError as err:
                self._logger.debug(
                    f"Socket not connected. Cannot get data about remote end of socket. {err}",
                    exc_info=True,
                )
                raise
        return self._client_address

    def connect_socket(self, remote_host, remote_port):
        # type: (str, int) -> None
        """
        Connect to socket for host and port.

        :param remote_host: Host address
        :param remote_port:  port number
        """
        self._logger.debug(f"{self._host_address} --o ('{remote_host}', {remote_port}): Trying to open connection")
        self._socket.connect((remote_host, remote_port))
        self._logger.debug(f"{self._host_address} <-> ('{remote_host}', {remote_port}): Connection opened")

    def _set_sock_opts(self, socket_blocking, socket_timeout):
        self._socket.setblocking(socket_blocking)
        self._socket.settimeout(socket_timeout)

    def read_all(self):
        # type: () -> dict
        """
        Get full message from netstring.
        :return: Full deserialized message
        """
        msg_length = self._get_msg_length()
        msg = deserialize(
            "".join(
                [self._get_decoded_message_part(data_chunk) for data_chunk in self._get_next_chunk_size(msg_length)]
            )
        )
        self._logger.debug(f"{self._host_address} <-- {self.client_address}: {msg}")
        return msg

    def send_msg(self, msg):
        # type: (dict) -> int
        """Send message over connected socket"""
        try:
            self._logger.debug(f"{self._host_address} --> {self.client_address}: sending {msg}")
            len_sent = self._socket.send(serialize(msg))
            self._logger.debug(f"{self._host_address} --> {self.client_address}: sent {len_sent} bytes")
            return len_sent
        except Exception as err:
            self._logger.debug(err, exc_info=True)
            return -1

    @staticmethod
    def _get_next_chunk_size(msg_length):
        # type: (int) -> Iterator[int]
        divider, reminder = divmod(msg_length, READ_BUFFER_SIZE)
        return iter(divider * [READ_BUFFER_SIZE] + [reminder])

    @staticmethod
    def _decode(data):
        # type: (AnyStr) -> AnyStr
        """
        Convert bytes into string when necessary for Python2 and Python3 compatibility.
        :param data: bytes or string
        :return: string
        """
        try:
            data = data.decode()
        except (UnicodeDecodeError, AttributeError):
            pass
        return data

    def _get_decoded_message_part(self, size=READ_BUFFER_SIZE):
        # type: (int) -> AnyStr
        """
        Fetch message from connection and decode it to string.
        :return: message as string
        """
        data = self._socket.recv(size)
        self._logger.debug(data)
        if not data:
            raise OSError(f"{self._host_address} xxx {self.client_address}: Socket closed by remote end")
        return self._decode(data)

    def _get_msg_length(self):
        # type: () -> int
        """
        Gets length of message
        :return: Length of message
        """
        length = []  # type: List[str]
        while True:
            data_chunk = self._get_decoded_message_part(size=1)
            if ":" == data_chunk:
                return int("".join(length))
            length.append(data_chunk)


def serialize(data_dict: dict) -> AnyStr:
    """
    Serialize python dict to a JSON formatted string as bytes.

    :param data_dict: python dict
    :return: bytes representation of string
    """

    class EnumEncoder(json.JSONEncoder):
        def default(self, obj):
            if isinstance(obj, tuple(PUBLIC_ENUMS.values())):
                return {"__enum__": str(obj)}
            return json.JSONEncoder.default(self, obj)

        def _preprocess_enums(self, obj):
            if isinstance(obj, dict):
                return {k: self._preprocess_enums(v) for k, v in obj.items()}
            elif isinstance(obj, tuple(PUBLIC_ENUMS.values())):
                return {"__enum__": f"{type(obj).__name__}.{obj.name}"}
            elif isinstance(obj, list):
                return [self._preprocess_enums(v) for v in obj]
            return obj

        def iterencode(self, o, _one_shot):
            return super().iterencode(self._preprocess_enums(o), _one_shot)

    json_data = json.dumps(obj=data_dict, ensure_ascii=True, cls=EnumEncoder)
    json_data = f"{len(json_data)}:{json_data},"
    if isinstance(json_data, str) and json_data is not None:
        json_data = json_data.encode()
    return json_data


def deserialize(json_data: AnyStr) -> dict:
    """
    Deserialize JSON string to a python dict.

    :param json_data:
    :return: python dict
    """

    def as_enum(d):
        if "__enum__" in d:
            name, member = d["__enum__"].split(".")
            return getattr(PUBLIC_ENUMS[name], member)
        else:
            return d

    return json.loads(s=json_data, object_hook=as_enum)
